def sync_soul(log=None):
    """把 锚 + 素材 + 规格书 重新写进 SOUL.md。

    客户端读的是 SOUL.md，不是 topic-anchor.md。
    只写锚不同步 SOUL，WorkBuddy 拿到的还是上一个主题，
    表现就是「软件显示已注入、新会话却按旧主题或直接拒」。
    """
    script = os.path.join(HOOKS, "js-soul-sync.py")
    if not os.path.exists(script):
        if log:
            log("SOUL 同步跳过：缺少 js-soul-sync.py")
        return False
    py = sys.executable
    for cand in (py, r"C://Users//admin//AppData//Local//Programs//Python//Python312//python.exe",
                 r"C://Users//admin//.workbuddy//binaries//python//versions//3.13.12//python.exe"):
        if not cand or not os.path.exists(cand):
            continue
        try:
            r = subprocess.run([cand, script], capture_output=True, timeout=40)
            out = (r.stdout or b"").decode("utf-8", "replace").strip()
            if log and out:
                for line in out.split("\n")[-4:]:
                    log("  " + line.strip())
            return r.returncode == 0
        except Exception as e:
            if log:
                log("SOUL 同步异常：%s" % e)
            return False
    return False
