def _relay_cfg_file():
    """优先改随包那份（打包版），没有再改 ~/.workbuddy 那份（开发版）。"""
    pkg = os.path.join(_appdir(), "relay", "relay-upstream.json")
    dev = os.path.join(WB, "relay-upstream.json")
    if os.path.exists(pkg):
        return pkg
    return dev


def read_relay_key():
    try:
        with io.open(_relay_cfg_file(), encoding="utf-8") as f:
            return json.load(f).get("apiKey", "")
    except Exception:
        return ""


def write_relay_key(key):
    p = _relay_cfg_file()
    try:
        try:
            with io.open(p, encoding="utf-8") as f:
                cfg = json.load(f)
        except Exception:
            cfg = {"host": "api.deepseek.com", "model": "deepseek-flash"}
        cfg["apiKey"] = key
        cfg.setdefault("host", "api.deepseek.com")
        cfg.setdefault("model", "deepseek-flash")
        os.makedirs(os.path.dirname(p), exist_ok=True)
        with io.open(p, "w", encoding="utf-8") as f:
            f.write(json.dumps(cfg, ensure_ascii=False))
        return True
    except Exception:
        return False


def patch_models_json(key=""):
    """把 WorkBuddy 的模型地址指到本机转发层。改前留一份 .bak，只改 url 和 apiKey。"""
    if not os.path.exists(MODELS_JSON):
        return False, "没找到 WorkBuddy 的 models.json"
    try:
        with io.open(MODELS_JSON, encoding="utf-8") as f:
            arr = json.load(f)
        if not isinstance(arr, list):
            return False, "models.json 格式不认"
        bak = MODELS_JSON + ".bak-coffee"
        if not os.path.exists(bak):
            shutil.copy2(MODELS_JSON, bak)
        changed = 0
        for m in arr:
            if not isinstance(m, dict):
                continue
            if m.get("url") != LOCAL_RELAY_URL:
                m["url"] = LOCAL_RELAY_URL
                changed += 1
            if key:
                m["apiKey"] = key
        with io.open(MODELS_JSON, "w", encoding="utf-8") as f:
            f.write(json.dumps(arr, ensure_ascii=False, indent=2))
        return True, "WorkBuddy 已指向本机转发层（%d 个模型）" % len(arr) if changed or key else "已经指向本机转发层"
    except Exception as e:
        return False, "改 models.json 失败：%s" % e


def restart_relay():
    """换 key 后必须重启转发层，它在启动时读一次配置。"""
    try:
        out = subprocess.run(
            ["wmic", "process", "where", "name='node.exe'", "get", "ProcessId,CommandLine"],
            capture_output=True).stdout.decode("utf-8", "replace")
        killed = 0
        for line in out.split("\n"):
            if "k19.mjs" in line:
                pid = line.strip().split()[-1]
                if pid.isdigit():
                    subprocess.run(["taskkill", "/PID", pid, "/F"], capture_output=True)
                    killed += 1
        time.sleep(1.0)
        node = os.path.join(_appdir(), "relay", "node.exe")
        js = os.path.join(_appdir(), "relay", "k19.mjs")
        if not (os.path.exists(node) and os.path.exists(js)):
            return False, "没找到随包的转发层"
        subprocess.Popen([node, js], cwd=os.path.join(_appdir(), "relay"),
                         stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL,
                         creationflags=0x00000008)
        for _ in range(40):
            try:
                with urllib.request.urlopen(LIVE_STATUS_URL, timeout=0.6) as r:
                    if r.status == 200:
                        return True, "转发层已重启"
            except Exception:
                time.sleep(0.25)
        return False, "转发层没起来，看 relay\\k19.log"
    except Exception as e:
        return False, "重启转发层失败：%s" % e


def check_key(key):
    """发一条 1 token 的请求验 key，不猜。"""
    try:
        body = json.dumps({
            "model": "deepseek-flash", "stream": False, "max_tokens": 1,
            "messages": [{"role": "user", "content": "hi"}],
        }).encode("utf-8")
        req = urllib.request.Request(
            "https://api.deepseek.com/chat/completions", data=body,
            headers={"Content-Type": "application/json", "Authorization": "Bearer " + key})
        with urllib.request.urlopen(req, timeout=20) as r:
            return r.status == 200, "key 可用"
    except urllib.error.HTTPError as e:
        return False, "key 被拒（HTTP %s）" % e.code
    except Exception as e:
        return False, "连通失败：%s" % e


