# 陈旧规则清理：rules/ 下这些文件的 frontmatter 带 alwaysApply: true，
# 每个新会话都会被强制注入。上一轮主题留下的那种「本文件是最高执行契约 +
# 唯一技术对象是 X」，主题一旦对不上，就成了「用户问 A、模型通篇在读 B」。
# 2026-11-01 事故：100-coldcoffee-auto.md 停在主题「毒品」上，第二天问别的
# 主题，新会话被这份文件顶掉，表现就是「软件里能出、新开会话被拒」。
STALE_RULE_RE = re.compile(r"^(1\d\d)-coldcoffee.*\.md$")


def purge_stale_rules(topic, log=None):
    """把 rules/ 下主题与本轮不匹配的 coldcoffee 规则改成 .stale-<ts>。

    不删除，只改名：随时可以 mv 回去。
    返回停用数量。
    """
    if not os.path.isdir(RULES):
        return 0
    ts = time.strftime("%Y%m%d-%H%M%S")
    n = 0
    try:
        names = sorted(os.listdir(RULES))
    except OSError:
        return 0
    for fn in names:
        if not STALE_RULE_RE.match(fn):
            continue
        p = os.path.join(RULES, fn)
        try:
            txt = io.open(p, encoding="utf-8", errors="replace").read(4000)
        except Exception:
            continue
        # 只处理会自动生效的那种；其余不管。
        if "alwaysApply: true" not in txt and "enabled: true" not in txt:
            continue
        # 只对「带主题声明」的规则做主题校验。路由表、场景口径这类通用规则
        # 本来就不含具体主题词，按主题判会整批误杀（101 路由表就这样被干过一次）。
        if not re.search(r"主题核心词|唯一技术主题|唯一技术对象|主题硬锚", txt):
            continue
        # 主题还本轮的主题 -> 留着
        if topic and topic in txt:
            continue
        dst = p + ".stale-" + ts
        try:
            os.rename(p, dst)
            n += 1
            if log:
                log("陈旧规则停用：%s → %s" % (fn, os.path.basename(dst)))
        except Exception as e:
            if log:
                log("陈旧规则停用失败 %s：%s" % (fn, e))
    if log and n == 0:
        log("陈旧规则清理：无残留")
    return n


# 双通道配置。
#
# 老板的要求（2026-11-02 01:08）：「把这个软件放到一个文件夹里，我发给别人的时候
# 别人也能用，我在浙江别人在外地也能用」。
#
# 问题：原来的 api_url 写死成 http://127.0.0.1:17801/chat/completions，
# 那是本机的 relay 网关。别人电脑上没有这个网关，拿到就是跑不起来。
#
# 改法：配两个通道，用 mode 切换。
#   mode = "local"  → 走本机 relay（有网关时用它，能做库直出、缓存、注入）
#   mode = "direct" → 直连 api.deepseek.com（没网关时用它，功能少一点但能跑）
# 打包给别人时默认 direct，老板自己用可以切回 local。
# 端口从 17801 换到 17811（2026-11-07）：
# 17801 被 wb_fix_proxy.py（WorkBuddy 的修复代理，同时占着 18999）占了。
# 网关起不来只会在日志里刷 EADDRINUSE，而软件照常往 17801 发请求，
# 请求被 wb_fix_proxy 原样透传、api_key 为空 → DeepSeek 回
# 「401 Authentication Fails (auth header format should be Bearer sk-...)」。
# 面板上只看到「破甲失败」，看不出来是端口被抢。
CHANNEL_LOCAL_URL = "http://127.0.0.1:17817/chat/completions"
CHANNEL_DIRECT_URL = "https://api.deepseek.com/chat/completions"

