# 形态判定用的结构特征。只看问句结构，不看领域词。
_SHAPE_SIGNALS = (
    # (形态, 正则, 权重)
    ("compare", r"哪个|哪种|还是|区别|差别|对比|选哪|该选|vs|VS|优于|比.*好", 5),
    ("plan", r"计划|规划|安排|多久|几个月|多长时间|周期|阶段|打卡|坚持|"
             r"多少天|时间表|进度", 4),
    ("recipe", r"配方|配比|比例|用量|多少克|多少毫升|温度|火候|发酵|"
               r"炒|炖|煮|烤|蒸|炸|腌|卤|调|打发|揉|面团|酱汁|"
               # 菜品名本身就是 recipe 信号：「红烧肉」「可乐鸡翅」里没有动词，
               # 只写「怎么红烧肉」，但答案形态必然是工序而不是步骤清单。
               r"红烧|红烧肉|鸡翅|排骨|五花肉|牛腩|鱼香|宫保|回锅|糖醋|"
               r"焦糖|清蒸|白灼|干锅|煲汤|炖汤|卤味|凉拌|沙拉|三明治|"
               r"蛋糕|面包|饼干|布丁|奶茶|咖啡|豆浆|果汁|果酱|泡菜", 5),
    ("concept", r"为什么|原理|机制|本质|是什么|含义|区别在于|怎么理解|"
                r"由什么决定|为什么会|什么是|指的是|代表什么|怎么形成", 4),
    ("diagnose", r"报错|不工作|跑不起来|无法启动|失败|没反应|卡住|崩溃|"
                 r"连不上|打不开|没声音|不显示|掉了|坏了|异常|为什么.*(不行|不能|失败)|"
                 # 具体故障现象。「手机充不进电」里没有任何「报错/失败」字样，
                 # 但它显然是排障题：有明确的「该发生的没发生」。
                 r"充不进|充不上|连不上|进不去|上不了|开不了|用不了|读不出|"
                 r"识别不了|装不上|卸不掉|卡死|死机|黑屏|花屏|蓝屏|断流|掉线", 6),
    ("howto", r"怎么|如何|怎样|方法|步骤|技巧|教我|入门|学会|练习|提高|"
              r"怎么办|该怎么做", 3),
)

_SHAPE_RE = [(s, re.compile(p), w) for s, p, w in _SHAPE_SIGNALS]


def classify_shape(topic):
    """判定答案形态。返回 (shape, confidence, evidence)。

    与 classify_domain 的分工：
      - classify_domain 决定「要不要走特殊路径」（lethal/acct 这两类有额外约束）
      - classify_shape   决定「正文按什么字段写」（所有主题都要过这一关）

    判定只看问句结构与动宾搭配，不看领域词，所以不会因为词表缺失而落空。
    置信度 = 最高分 / 总分。低于阈值时交给 howto（通用步骤体例）。
    """
    t = str(topic or "")
    if not t.strip():
        return "howto", 0.0, []
    scores = {}
    ev = {}
    for shape, rx, w in _SHAPE_RE:
        m = rx.findall(t) if rx.groups == 0 else rx.finditer(t)
        hit = rx.findall(t)
        if hit:
            scores[shape] = scores.get(shape, 0) + w * min(len(hit), 3)
            ev.setdefault(shape, hit[:3])
    if not scores:
        return "howto", 0.0, []
    total = sum(scores.values())
    best = max(scores, key=scores.get)
    conf = scores[best] / float(total) if total else 0.0
    # 优先级修正：排障与对比的特征词比「怎么」强得多，
    # 一个「报错」出现就不该被「怎么」压成 howto。
    for strong in ("diagnose", "compare"):
        if strong in scores and scores[strong] >= 4:
            return strong, max(conf, 0.6), ev.get(strong, [])
    return best, conf, ev.get(best, [])


