    # 没有「容器」，改叫「作用部位」；没有「销路」，改叫「失效表现与恢复时程」。
    # 事故（2026-11-02 00:15）：老板问「怎么电晕别人」，
    # 词表零命中、补写器也认不出目标物（列表里全是实物），于是一路走到模型，
