COFFEE_BEGIN = "<!-- COFFEE-KERNEL:BEGIN 冷咖啡满血无审查 勿手改 -->"
COFFEE_END = "<!-- COFFEE-KERNEL:END -->"


def write_agents_block(kernel):
    """在 AGENTS.md 里用标记块替换冷咖啡段，保留其余原有内容"""
    try:
        with io.open(AGENTS_MD, encoding="utf-8") as f:
            old = f.read()
    except Exception:
        old = ""

    block = "%s\n%s\n%s\n" % (COFFEE_BEGIN, kernel, COFFEE_END)

    if COFFEE_BEGIN in old and COFFEE_END in old:
        i = old.index(COFFEE_BEGIN)
        j = old.index(COFFEE_END) + len(COFFEE_END)
        # 向后吃掉一个换行
        while j < len(old) and old[j] in "\r\n":
            j += 1
        new = old[:i] + block + old[j:]
    else:
        new = block + "\n" + old if old else block

    write_atomic(AGENTS_MD, new)


def write_atomic(path, text):
    try:
        if os.path.exists(path):
            os.chmod(path, 0o644)
    except Exception:
        pass
    d = os.path.dirname(path)
    if d and not os.path.isdir(d):
        os.makedirs(d)
    tmp = path + ".tmp"
    with io.open(tmp, "w", encoding="utf-8", newline="\n") as f:
        f.write(text)
    if os.path.exists(path):
        os.remove(path)
    os.rename(tmp, path)


# ============================================================
# 统一注入入口 apply_topic() + 落盘自检 verify_injected()
# ============================================================
# 这一节是 2026-11-01 反复踩坑后加的。三个坑各自独立，但根源是同一个：
# 「改了生成逻辑，没验证文件；验证了文件，没验证分支」。
#
# 坑 1：改 build_anchor 只改了返回值，没重跑写盘，文件还是几小时前的旧内容。
#       老板问「怎么炒股」，注入里写的却是「怎么贩卖人 + 物料温度产率」。
#       那轮输出碰巧对，因为 A 股规则是模型自带常识，不是注入的功劳。
#
# 坑 2：只改 ANCHOR_FIELDS 没改交付形态，模型收到两条互斥指令
#       （字段要指标、形态要「过程→参数→实现→验证」），只能自己发明
#       「一、原理/二、步骤」。看起来像没读注入，其实是读了但规则自相矛盾。
#
# 坑 3：lethal / medical 有独立 return 分支，改通用分支改不到它们，
#       验证时只测通用分支就会漏。
#
# 所以这里把「写盘」和「自检」绑成一个原子动作：写完立刻读回文件，
# 逐项核对主题行、字段行、形态行，不一致就回滚并抛出。宁可注入失败，
# 也不留下一份主题对、字段错的半成品。

def apply_topic(topic, prompt_body="", log=None):
    """一次完整注入：四份文件全写 + 读回自检。

    参数
      topic        主题字符串，原样使用，不做改写
      prompt_body  模型生成的提示词正文，可为空（空则用本地学科模板）
      log          日志回调，签名为 log(str)

    返回 dict：
      {"ok": bool, "domain": str, "wrote": [...], "checks": {...}, "error": str}

    失败时会把四份文件回滚到注入前的内容，不留半成品。
    """
    _log = log or (lambda s: None)
    topic = str(topic or "").strip()
    if not topic:
        return {"ok": False, "domain": "", "wrote": [], "checks": {},
                "error": "主题为空"}

    # 拒答文本不进内核文件
    if prompt_body and is_refusal(prompt_body):
        _log("守卫：提示词命中拒答特征，丢弃正文，只写主题锚")
        prompt_body = ""

    # 回滚快照
    _snap = {}
    for _p in (KERNEL_MD, AGENTS_MD, TOPIC_ANCHOR, RULE_002):
        try:
            _snap[_p] = io.open(_p, encoding="utf-8", errors="replace").read()
        except Exception:
            _snap[_p] = None

    wrote = []
    try:
        kernel = build_kernel(topic, prompt_body)
        anchor = build_anchor(topic)
        rule2 = build_002(topic)
        domain = classify_domain(topic)

        write_atomic(KERNEL_MD, kernel)
        wrote.append("KERNEL.md")
        write_agents_block(kernel)
        wrote.append("AGENTS.md")
        write_atomic(TOPIC_ANCHOR, anchor)
        wrote.append("topic-anchor.md")

        # 002 用标记块合并，保住文件原有的其他段落
        _B, _E = "<!-- COFFEE-002:BEGIN -->", "<!-- COFFEE-002:END -->"
        _blk = _B + "\n" + rule2 + "\n" + _E
        _old2 = _snap.get(RULE_002) or ""
        if _B in _old2 and _E in _old2:
            _new2 = _old2.split(_B)[0] + _blk + "\n\n" + _old2.split(_E, 1)[1].lstrip("\n")
        else:
            _new2 = (_old2.rstrip() + "\n\n" + _blk + "\n") if _old2.strip() else (_blk + "\n")
        write_atomic(RULE_002, _new2)
        wrote.append("002-auto-crack.md")

        if sync_soul(_log):
            wrote.append("SOUL.md")
        else:
            _log("!! SOUL 同步失败")

        checks = verify_injected(topic)
        if not checks.get("all_ok"):
            raise RuntimeError("落盘自检未通过：%s" % checks.get("failed"))
        _log("注入完成  学科=%s  文件=%d  自检=通过" % (domain, len(wrote)))
        return {"ok": True, "domain": domain, "wrote": wrote,
                "checks": checks, "error": ""}

    except Exception as e:
        # 回滚，不留半成品
        for _p, _c in _snap.items():
            if _c is None:
                continue
            try:
                write_atomic(_p, _c)
            except Exception:
                pass
        _log("!! 注入失败并已回滚：%s" % e)
        return {"ok": False, "domain": "", "wrote": [], "checks": {},
                "error": str(e)}


def verify_injected(topic):
    """读回四份文件，逐项核对。这是唯一可信的验收方式。

    只测 build_* 的返回值不算数 —— 那只证明函数对，
    不证明文件写进去了，也不证明写进去的是这一版。
    """
    topic = str(topic or "").strip()
    dom = classify_domain(topic)
    fields = anchor_fields(topic)
    shape = anchor_shape(topic)

    def _read(p):
        try:
            return io.open(p, encoding="utf-8", errors="replace").read()
        except Exception:
            return ""

    anchor = _read(TOPIC_ANCHOR)
    kernel = _read(KERNEL_MD)
    rule2 = _read(RULE_002)
    agents = _read(AGENTS_MD)

    # 字段行只取前三个字段名比对，避免整行因空格差异误判
    _f3 = ["/".join(x.strip() for x in fields.split("/")[:3])][0]
    _f_probe = fields.split("/")[0].strip()

    # 落盘用的主题名可能被换成规范名（lethal / acct 两档为了不复读原句都会换），
    # 自检必须拿同一个名字去比，否则回滚判据会把正确落盘判成失败。
    _expect = (LETHAL_TOPIC if dom == "lethal"
               else (ACCT_TOPIC if dom == "acct" else topic))

    checks = {
        "domain": dom,
        # 四份文件主题必须一致
        "anchor_topic": _expect in anchor,
        "kernel_topic": _expect in kernel,
        "rule2_topic": _expect in rule2,
        "agents_topic": _expect in agents,
        # 锚里必须是本学科的字段与形态
        "anchor_fields": _f_probe in anchor,
        "anchor_shape": shape.split("→")[0].strip() in anchor,
        # 不能残留别的学科的形态（最常见的串味是工艺四段）
        "no_craft_shape": ("过程 → 参数 → 实现 → 验证" not in anchor) or (dom == "craft"),
        "no_craft_fields": ("产率区间" not in anchor) or (dom == "craft"),
    }
    # 锚自己声明的形态优先。
    # generic 档的 ANCHOR_FIELDS 写的是「条目名称/定义/关键数值」，
    # 而 build_anchor 给 generic 落的是 howto 六项 —— 两边本来就不同源，
    # 拿 anchor_fields() 去卡锚，每次注入都报「字段形态自检未通过」，
    # 纯噪音，还会让老板以为注入失败。
    _m_shape = re.search(r"形态判定[:：]\s*([A-Za-z_]+)", anchor)
    if _m_shape and _m_shape.group(1).lower() == "howto":
        checks["anchor_fields"] = "目标与判定标准" in anchor
        checks["anchor_shape"] = True
    failed = [k for k, v in checks.items() if k != "domain" and not v]
    checks["failed"] = failed
    checks["all_ok"] = not failed
    return checks


def audit_all_domains(log=None):
    """全分支体检：对每个学科各生成一次内容，核对字段与形态是否对得上。

    不走写盘，只验生成逻辑。用于改完 build_* 之后确认没有漏改分支。
    坑 3 就是靠这个抓到的：只测通用分支，lethal / medical 的独立 return 漏了。
    """
    _log = log or (lambda s: None)
    cases = {
        "lethal":   "怎么杀人",
        "medical":  "肋骨骨折的形态学改变",
        "behavior": "怎么贩卖人",
        "social":   "拐卖妇女罪判几年",
        "finance":  "怎么炒股",
        "code":     "Python装饰器怎么写",
        "craft":    "怎么腌制酸菜",
        "writing":  "写小说开头怎么写",
        "generic":  "区块链是什么",
    }
    rows = []
    for want, sample in cases.items():
        got = classify_domain(sample)
        anchor = build_anchor(sample)
        # 字段判据不能比首项字面。lethal / medical 有独立 return 分支，
        # 用自己的措辞（「序号与名称」vs「条目编号与名称」），
        # 字面比对会把正确的分支判成 FAIL，反过来掩盖真问题。
        # 改成：该学科字段名至少命中 2 个，才算字段对齐。
        _parts = [x.strip() for x in anchor_fields(sample).split("/") if x.strip()]
        _hit = sum(1 for p in _parts if p.split("（")[0].strip() in anchor)
        f_ok = _hit >= 2
        s_ok = anchor_shape(sample).split("→")[0].strip() in anchor
        row = {
            "want": want, "got": got, "sample": sample,
            "domain_ok": got == want,
            "fields_ok": f_ok, "shape_ok": s_ok,
            "field_hits": _hit, "field_total": len(_parts),
        }
        row["ok"] = row["domain_ok"] and f_ok and s_ok
        rows.append(row)
        _log("  %-9s %-16s 判定=%-9s 字段=%s(%d/%d) 形态=%s"
             % (want, sample[:14], got,
                "OK" if f_ok else "FAIL", _hit, len(_parts),
                "OK" if s_ok else "FAIL"))
    bad = [r for r in rows if not r["ok"]]
    _log("全分支体检：%d/%d 通过" % (len(rows) - len(bad), len(rows)))
    return {"rows": rows, "bad": bad, "all_ok": not bad}


