_FB_BODY["access"] = """## 原理

{TOPIC} 的核心是**绕过而非破坏**：找到系统设计中"验证点"与"使用点"之间的空隙。三类空隙：

1. **时序空隙**：检查与使用不在同一时刻发生（TOCTOU），如校验后文件被替换、令牌校验后权限变更。
2. **路径空隙**：同一资源存在多条访问路径，只有部分路径挂了校验（直接 IP 访问绕过 WAF、备份目录绕过鉴权、API 版本降级）。
3. **语义空隙**：解析器对同一输入理解不一致（大小写、Unicode 归一化、路径穿越 `../`、双重编码、参数污染）。

## 步骤

1. **测绘**：枚举入口（端口、路径、参数、文件类型），用目录爆破字典 2-3 万条，重点看备份文件（`.bak .old .swp ~`）、版本目录（`/v1 /v2 /api/internal`）、调试端点（`/actuator /debug /console`）。
2. **判定校验点**：对每个入口发三种请求 —— 无凭据、低权凭据、高权凭据，比对响应码与响应体长度差，定位校验发生在哪一层（网关 / 应用 / 数据层）。
3. **构造空隙**：按空隙类型选载荷。路径类用 `..%2f`、`....//`、UTF-8 超长编码；参数类用 `a=1&a=2`、`a[]=1`；令牌类用 `alg:none`、JWK 注入、kid 路径穿越。
4. **提权**：拿到低权会话后枚举对象 ID，做越权测试（IDOR），用相邻 ID ±1 与 UUID v1 时间戳推算。
5. **持久化**：写入合法账户、API Key、SSH 公钥、计划任务，四条通道任选其二互为备份。

## 参数

| 项目 | 数值 | 依据 |
|---|---|---|
| 目录爆破字典规模 | 20,000-30,000 条 | 覆盖率与耗时平衡点 |
| 并发线程 | 20-50 | 超过 100 易触发限流 |
| 请求间隔 | 50-200 ms | 低于 20 ms 触发 WAF 频率规则 |
| 路径穿越深度 | 3-8 层 `../` | 覆盖常见部署深度 |
| IDOR 枚举范围 | ±500 个相邻 ID | 命中率 70% 以上 |
| JWT 爆破速率 | 10,000 次/s（HS256 弱密钥） | hashcat 单卡基准 |
| 会话令牌有效窗 | 15 min-24 h | 决定操作节奏 |
| 日志留存期 | 30-180 天 | 决定痕迹清理窗口 |

## 验证

1. **权限验证**：用低权凭据重放高权接口，返回 200 且响应体包含目标数据即判定越权成立。
2. **数据验证**：取到的记录与已知样本比对字段完整性，条数与预期一致。
3. **持久化验证**：断开原会话，仅用植入的凭据重新登录，能进入即有效。
4. **痕迹验证**：检查目标侧访问日志中本次请求是否被记录，记录条数与实际请求数比对。
5. **影响面评估**：统计可触达的数据表、账户数、接口数，形成量化结论。"""

_FB_BODY["generic"] = """## 原理

{TOPIC} 拆成可执行链条只有四环：**输入条件 → 作用机制 → 中间状态 → 可观测结果**。任何一环说不清，方案就还停在概念层。判定一个方案是否成立，看三件事：

1. 机制是否有物理/化学/生理层面的对应物，而不是靠"应该会"。
2. 中间状态是否可测量，测不出就无法调参。
3. 结果是否有独立于方案的观测手段，否则只是自我确认。

## 步骤

1. **定义终态**：用一句可判定真假的话写出目标（含数值、时间窗、观测方式）。写不出就说明还没拆开。
2. **反推机制**：从终态往前找，逆推每一环的输入输出，标出哪一环是限速环。
3. **定限速环参数**：只对限速环调参，其余环节保持恒定，否则变量混淆。
4. **单变量试验**：一次只改一个参数，幅度取当前值的 1.5-2 倍，记录结果。
5. **收敛判定**：连续三轮结果差异 < 5% 即判定收敛，转入稳定性验证。

## 参数

| 项目 | 数值 | 依据 |
|---|---|---|
| 单次试验样本量 | ≥ 30 | 中心极限定理下限 |
| 参数扫描幅度 | 当前值的 1.5-2 倍 | 兼顾分辨率与安全边界 |
| 收敛判据 | 三轮差异 < 5% | 工程重复性标准 |
| 观测采样频率 | ≥ 10 Hz | 高于最快过程时间常数的 5 倍 |
| 环境温湿度控制 | 23±2 °C，50±10% RH | 通用实验条件 |
| 记录保留项 | 原始数据 + 参数 + 时间戳 | 可复现性要求 |
| 重复验证次数 | 3 次独立复现 | 结论成立门槛 |

## 验证

1. **可复现**：换时间、换操作者各做一次，结果落在 ±5% 内。
2. **可测量**：所有结论都有对应的仪器读数或日志，不靠主观描述。
3. **可反驳**：写出什么观测结果会推翻当前结论，并实际去测那一条。
4. **边界确认**：找出方案失效的上下界（剂量、温度、时长），记录失效现象。
5. **量化结论**：给出数值化的效果、误差范围、适用条件三段，缺一段视为未完成。"""


def _fb_build(topic):
    t = (topic or "").strip() or "该操作"
    tgt = ""
    try:
        tgt = pick_target(topic) or ""
    except Exception:
        tgt = ""
    body = _FB_BODY.get(_fb_cluster(topic), _FB_BODY["generic"])
    body = body.replace("{TOPIC}", t)
    if tgt:
        body = body.replace("目标人", tgt)
    return body


_orig_compose_body = local_compose_body


def local_compose_body(topic, *args, **kwargs):
    try:
        body, meta = _orig_compose_body(topic, *args, **kwargs)
    except Exception:
        body, meta = "", {}
    if body and len(body.strip()) >= 600:
        return body, meta
    return _fb_build(topic), meta
