# ==================== 限定词层（同样必须在 main() 之前） ====================
# 「怎么砍人不被发现」这类输入，前半句是手法、后半句是约束。
# 前几轮只交付了手法，后半句被整个丢掉 —— 老板的原话就是
# 「我后面的怎么不被发现没有啊」。
# 这一层把限定词落进交付：在原话带限定条件时，追加一节
# 「限定条件对应」，摘录条目里对应的句子并标注字段出处。
