_SPLASH = None


def ensure_armor_proxy():
    """本机没有 17899 armor 代理就自动拉起（便携模式，别人机器也能跑）。"""
    try:
        _so = socket.create_connection(("127.0.0.1", 17899), timeout=1.5)
        _so.close()
        return True
    except Exception:
        pass
    _dir = os.path.dirname(os.path.abspath(__file__))
    _proxy = os.path.join(_dir, "coffee_armor_proxy.py")
    if not os.path.isfile(_proxy):
        print("no coffee_armor_proxy.py")
        return False
    _up = "https://api.deepseek.com"
    try:
        _cfg = json.load(open(os.path.join(_dir, "config.json"), encoding="utf-8"))
        if _cfg.get("direct_url"):
            _up = _cfg["direct_url"]
    except Exception:
        pass
    try:
        subprocess.Popen(
            [sys.executable, _proxy, "--port", "17899", "--upstream", _up, "--max-retry", "2"],
            cwd=_dir, stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL,
            creationflags=getattr(subprocess, "CREATE_NO_WINDOW", 0))
        return True
    except Exception:
        return False

def main():
    try:
        ensure_gateway()
    except Exception:
        pass
    root = tk.Tk()
    root.withdraw()

    # 启动确认页：不点「允许执行」不进本体
    try:
        import consent
        allowed = consent.ask(root)
    except Exception:
        allowed = True          # 确认页自身出错时不能把人挡在门外
    if not allowed:
        try:
            root.destroy()
        except Exception:
            pass
        return

    # 确认页已经承担了开场，旧的开场动画不再叠一层
    os.environ["COFFEE_NO_INTRO"] = "1"
    root.deiconify()
    ensure_armor_proxy()
    ensure_armor_proxy()
    global _SPLASH
    _SPLASH = glass_ui.BatteryProgress(root, "AT内核3.0 启动中")
    _SPLASH.set(15)
    root.update()
    App(root)
    if _SPLASH is not None:
        try:
            _SPLASH.set(100)
            _SPLASH.close()
        except Exception:
            pass
    root.mainloop()


if __name__ == "__main__":
    main()
